import java.nio.file.*;import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;
/** Whole archive and ownership-state audit, separate from still-open old-scene consumer qualification. */
public final class CompanionNatureDelta {
 public static void main(String[]a)throws Exception{String p="local/lito381/server/";var expected=new TreeSet<String>();for(var n:List.of("ClientSession","NativeReturnNatureMaterialAction","NativeSummonGroundTransfer$Stage"))expected.add(p+n+".class");var additions=new TreeSet<String>();additions.add(p+"NativeCompanionNature.class");try(var before=new JarFile(a[0]);var after=new JarFile(a[1])){var changed=new TreeSet<String>();var original=new HashSet<String>();for(var e:Collections.list(before.entries())){original.add(e.getName());var n=after.getJarEntry(e.getName());if(n==null)throw new AssertionError("removed "+e.getName());if(!Arrays.equals(before.getInputStream(e).readAllBytes(),after.getInputStream(n).readAllBytes()))changed.add(e.getName());}var fresh=new TreeSet<String>();for(var e:Collections.list(after.entries()))if(!original.contains(e.getName()))fresh.add(e.getName());if(!changed.equals(expected)||!fresh.equals(additions))throw new AssertionError("archive delta "+changed+" "+fresh);
  for(var n:fresh){var c=new ClassNode();new ClassReader(after.getInputStream(after.getJarEntry(n))).accept(c,0);for(var f:c.fields){if(f.desc.equals("L"+p+"ClientSession;")||f.desc.equals("L"+p+"GameHub;")||f.desc.contains("ThreadLocal")||f.desc.contains("Executor"))throw new AssertionError("strong live owner or execution state "+n+" "+f.name);if((f.access&Opcodes.ACC_STATIC)!=0&&!f.desc.equals("Ljava/lang/String;"))throw new AssertionError("new static registry/state "+n+" "+f.name);}for(var m:c.methods)for(var i:m.instructions){if(i instanceof TypeInsnNode t&&t.getOpcode()==Opcodes.NEW&&(t.desc.equals("java/lang/Thread")||t.desc.contains("ThreadLocal")||t.desc.contains("ThreadPool")||t.desc.equals("java/util/Timer")))throw new AssertionError("new executor owner "+t.desc);if(i instanceof MethodInsnNode call&&(call.owner.startsWith("java/sql/")||call.owner.startsWith("javax/sql/")||call.owner.startsWith("java/nio/file/")||call.owner.contains("AccountRepository")||call.owner.endsWith("GameStateStore")||call.name.equals("nativeDeInventory")))throw new AssertionError("new direct SQL/file/player-inventory dependency "+call.owner+"."+call.name);}}
  for(var name:List.of("ClientSession","NativeReturnNatureMaterialAction","NativeSummonGroundTransfer$Stage")){var b=new ClassNode();var c=new ClassNode();new ClassReader(before.getInputStream(before.getJarEntry(p+name+".class"))).accept(b,0);new ClassReader(after.getInputStream(after.getJarEntry(p+name+".class"))).accept(c,0);if(c.fields.size()!=b.fields.size())throw new AssertionError("no new player/helper fields");}
 }System.out.println("PASS exact three changed/one fresh classes; remaining archive identical; no new fields; weak live owner/Hub; no new workers/timers/ThreadLocals/global registry or direct SQL/player-inventory/file calls");}
}
